var i=`1118-southern-fried-chicken`;var n=`world-1118`;var a=`US`;var r=`northern-america`;var s=4;var o=156;var l={en:`Southern Fried Chicken`,ua:`Смажена курка по-південному`};var h={en:`Southern Fried Chicken is a dish from United States prepared with chicken drumstick, buttermilk, hot sauce, all-purpose flour. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Смажена курка по-південному, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: куряча гомілка, сколотини, гострий соус, пшеничне борошно універсальне. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 120 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 120 хвилин.`,t:[`marinating`],m:120,i:[[`chicken-drumstick`,1e3,`g`],[`buttermilk`,490,`ml`],[`hot-sauce`,45,`ml`],[`table-salt`,10,`g`]]},{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:12,i:[[`all-purpose-flour`,360,`g`],[`cornstarch`,85,`g`],[`smoked-paprika`,7,`g`],[`ground-black-pepper`,6,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 21 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 21 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:21,i:[[`canola-oil`,1100,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`]]}];var u={slug:i,id:n,country:`US`,region:r,servings:4,minutes:156,title:l,text:h,steps:d};export{a as country,u as default,n as id,o as minutes,r as region,s as servings,i as slug,d as steps,h as text,l as title};